BEGIN;
CREATE TABLE public.pace_polls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),subject_id uuid NOT NULL REFERENCES subjects(id),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120),class_date date NOT NULL,deadline timestamptz NOT NULL,enabled boolean NOT NULL DEFAULT true,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.pace_votes(poll_id uuid REFERENCES public.pace_polls(id) ON DELETE CASCADE,student_id uuid REFERENCES public.students(id) ON DELETE CASCADE,choice text NOT NULL CHECK(choice IN ('fast','perfect','slow')),PRIMARY KEY(poll_id,student_id));
ALTER TABLE public.pace_polls ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.pace_polls FROM anon,authenticated;
REVOKE ALL ON private.pace_votes FROM PUBLIC,anon,authenticated;
CREATE FUNCTION private.manage_pace(bid uuid,subject uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT private.is_owner() OR EXISTS(SELECT 1 FROM teacher_batch_subjects WHERE teacher_id=auth.uid() AND batch_id=bid AND subject_id=subject) $$;
CREATE FUNCTION public.pace_catalog() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE sid uuid; manager boolean; result jsonb; BEGIN
 IF private.current_role() NOT IN ('owner','teacher','student') OR NOT EXISTS(SELECT 1 FROM users WHERE id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Not authorized';END IF;
 manager:=private.current_role() IN ('owner','teacher');SELECT student_id INTO sid FROM users WHERE id=auth.uid();
 SELECT jsonb_build_object('manager',manager,'scopes',coalesce((SELECT jsonb_agg(jsonb_build_object('batch_id',bs.batch_id,'subject_id',bs.subject_id,'batch',b.name,'subject',s.name)) FROM batch_subjects bs JOIN batches b ON b.id=bs.batch_id JOIN subjects s ON s.id=bs.subject_id WHERE manager AND b.is_active AND private.manage_pace(bs.batch_id,bs.subject_id)),'[]'::jsonb),'polls',coalesce((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('batch',b.name,'subject',s.name,'voted',EXISTS(SELECT 1 FROM private.pace_votes v WHERE v.poll_id=p.id AND v.student_id=sid)) ORDER BY p.created_at DESC) FROM pace_polls p JOIN batches b ON b.id=p.batch_id JOIN subjects s ON s.id=p.subject_id WHERE (manager AND private.manage_pace(p.batch_id,p.subject_id)) OR (NOT manager AND p.enabled AND p.deadline>now() AND private.student_in_batch(p.batch_id))),'[]'::jsonb),'trends',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT p.batch_id,b.name AS batch,s.name AS subject,date_trunc('week',p.class_date::timestamp)::date AS week,count(*) AS responses,count(*) FILTER(WHERE v.choice='fast') AS fast,count(*) FILTER(WHERE v.choice='perfect') AS perfect,count(*) FILTER(WHERE v.choice='slow') AS slow FROM pace_polls p JOIN private.pace_votes v ON v.poll_id=p.id JOIN batches b ON b.id=p.batch_id JOIN subjects s ON s.id=p.subject_id WHERE manager AND p.deadline<=now() AND private.manage_pace(p.batch_id,p.subject_id) GROUP BY p.batch_id,b.name,p.subject_id,s.name,date_trunc('week',p.class_date::timestamp) HAVING count(DISTINCT v.student_id)>=5) t),'[]'::jsonb)) INTO result;RETURN result;END $$;
CREATE FUNCTION public.save_pace_poll(p_batch uuid,p_subject uuid,p_title text,p_date date,p_deadline timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE pid uuid;BEGIN
 IF NOT private.manage_pace(p_batch,p_subject) OR NOT EXISTS(SELECT 1 FROM users WHERE id=auth.uid() AND status='active') OR NOT EXISTS(SELECT 1 FROM batch_subjects WHERE batch_id=p_batch AND subject_id=p_subject) THEN RAISE EXCEPTION 'Choose an assigned batch and subject';END IF;
 IF p_deadline<=now() OR p_deadline>now()+interval '30 days' OR p_date>(now() AT TIME ZONE 'Asia/Kolkata')::date THEN RAISE EXCEPTION 'Choose a completed class and a deadline within 30 days';END IF;
 INSERT INTO pace_polls(batch_id,subject_id,title,class_date,deadline,created_by) VALUES(p_batch,p_subject,p_title,p_date,p_deadline,auth.uid()) RETURNING id INTO pid;
 PERFORM private.notify_batch_students(p_batch,'Teaching pace feedback opened',p_title,'schedule');RETURN pid;END $$;
CREATE FUNCTION public.toggle_pace_poll(p_id uuid,p_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p pace_polls;BEGIN SELECT * INTO p FROM pace_polls WHERE id=p_id FOR UPDATE;IF p.id IS NULL OR NOT private.manage_pace(p.batch_id,p.subject_id) OR NOT EXISTS(SELECT 1 FROM users WHERE id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Not authorized';END IF;IF p_enabled AND p.deadline<=now() THEN RAISE EXCEPTION 'This deadline has passed. Create a new poll';END IF;UPDATE pace_polls SET enabled=p_enabled WHERE id=p_id;END $$;
CREATE FUNCTION public.vote_teaching_pace(p_id uuid,p_choice text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p pace_polls;sid uuid;BEGIN SELECT * INTO p FROM pace_polls WHERE id=p_id FOR UPDATE;SELECT student_id INTO sid FROM users WHERE id=auth.uid() AND role='student' AND status='active';IF sid IS NULL OR p.id IS NULL OR NOT p.enabled OR p.deadline<=now() OR NOT private.student_in_batch(p.batch_id) THEN RAISE EXCEPTION 'Voting is not available';END IF;INSERT INTO private.pace_votes VALUES(p_id,sid,p_choice);END $$;
REVOKE ALL ON FUNCTION public.pace_catalog(),public.save_pace_poll(uuid,uuid,text,date,timestamptz),public.toggle_pace_poll(uuid,boolean),public.vote_teaching_pace(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pace_catalog(),public.save_pace_poll(uuid,uuid,text,date,timestamptz),public.toggle_pace_poll(uuid,boolean),public.vote_teaching_pace(uuid,text) TO authenticated;
REVOKE ALL ON FUNCTION private.manage_pace(uuid,uuid) FROM PUBLIC,anon,authenticated;
COMMIT;
